    iron_smithhammerwedge = { name = "Železni klin za kovaška kladiva", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni klin za kovaška kladiva za kovace." },
    bronze_smithhammerwedge = { name = "Bronast klin za kovaška kladiva", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast klin za kovaška kladiva za kovace." },
    silver_smithhammerwedge = { name = "Srebrn klin za kovaška kladiva", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn klin za kovaška kladiva za kovace." },
    gilded_smithhammerwedge = { name = "Pozlačen klin za kovaška kladiva", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen klin za kovaška kladiva za kovace." },
    jewel_set_smithhammerwedge = { name = "Draguljast klin za kovaška kladiva", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast klin za kovaška kladiva za kovace." },
    royal_sovereign_smithhammerwedge = { name = "Kraljevski suveren klin za kovaška kladiva", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren klin za kovaška kladiva z biseri za krono." },
}
local BUILDINGS = {
    smithhammerwedge_workshop = { name = "Smithhammerwedge delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
