    sovereign_smithhammerwedge_palace = { name = "Suverena smithhammerwedge palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SmithHammerWedgeMaker.ironStock=18; SmithHammerWedgeMaker.bronzeStock=14; SmithHammerWedgeMaker.woodStock=10; SmithHammerWedgeMaker.leatherStock=8; SmithHammerWedgeMaker.silverStock=8; SmithHammerWedgeMaker.goldStock=6; SmithHammerWedgeMaker.jewelStock=4; SmithHammerWedgeMaker.pearlStock=4
SmithHammerWedgeMaker.productStock = {}; SmithHammerWedgeMaker.buildings = {}; SmithHammerWedgeMaker.maker = nil; SmithHammerWedgeMaker.activeMaking = {}; SmithHammerWedgeMaker.totalProducts = 0; SmithHammerWedgeMaker.dayTimer = 0
function SmithHammerWedgeMaker.init() SmithHammerWedgeMaker.ironStock=18; SmithHammerWedgeMaker.bronzeStock=14; SmithHammerWedgeMaker.woodStock=10; SmithHammerWedgeMaker.leatherStock=8; SmithHammerWedgeMaker.silverStock=8; SmithHammerWedgeMaker.goldStock=6; SmithHammerWedgeMaker.jewelStock=4; SmithHammerWedgeMaker.pearlStock=4; SmithHammerWedgeMaker.productStock={}; SmithHammerWedgeMaker.buildings={}; SmithHammerWedgeMaker.maker=nil; SmithHammerWedgeMaker.activeMaking={}; SmithHammerWedgeMaker.totalProducts=0; SmithHammerWedgeMaker.dayTimer=0; print("[SmithHammerWedgeMaker] Royal Smith Hammer Wedge Maker System initialized (6 products, 4 buildings)") end
function SmithHammerWedgeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SmithHammerWedgeMaker.maker={name=n or ("Klinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klinar najet: %s (spretnost: %d)",SmithHammerWedgeMaker.maker.name,s),"success") end; return true end
function SmithHammerWedgeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SmithHammerWedgeMaker.build(id) local ok,e=SmithHammerWedgeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SmithHammerWedgeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SmithHammerWedgeMaker.getQualityBonus() local b=0; for _,bd in ipairs(SmithHammerWedgeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SmithHammerWedgeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SmithHammerWedgeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SmithHammerWedgeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SmithHammerWedgeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SmithHammerWedgeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SmithHammerWedgeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SmithHammerWedgeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SmithHammerWedgeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SmithHammerWedgeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SmithHammerWedgeMaker.buildings==0 then return false,"Potrebna klinska delavnica" end; if not SmithHammerWedgeMaker.maker then return false,"Potreben klinar" end; return true end
function SmithHammerWedgeMaker.make(pt,qty) qty=qty or 1; local ok,e=SmithHammerWedgeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SmithHammerWedgeMaker.ironStock=SmithHammerWedgeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SmithHammerWedgeMaker.bronzeStock=SmithHammerWedgeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SmithHammerWedgeMaker.woodStock=SmithHammerWedgeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SmithHammerWedgeMaker.leatherStock=SmithHammerWedgeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SmithHammerWedgeMaker.silverStock=SmithHammerWedgeMaker.silverStock-d.silverCost*qty end; if d.goldCost then SmithHammerWedgeMaker.goldStock=SmithHammerWedgeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SmithHammerWedgeMaker.jewelStock=SmithHammerWedgeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SmithHammerWedgeMaker.pearlStock=SmithHammerWedgeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SmithHammerWedgeMaker.maker then t=math.max(1,t-math.floor(SmithHammerWedgeMaker.maker.skill/13)) end; table.insert(SmithHammerWedgeMaker.activeMaking,{id="smithhammerwedge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SmithHammerWedgeMaker.completeMaking(m) local q=1.0+(SmithHammerWedgeMaker.getQualityBonus()/100); if SmithHammerWedgeMaker.maker then q=q+(SmithHammerWedgeMaker.maker.skill/140) end; q=math.min(2.5,q); SmithHammerWedgeMaker.productStock[m.productType]=(SmithHammerWedgeMaker.productStock[m.productType] or 0)+m.quantity; SmithHammerWedgeMaker.totalProducts=SmithHammerWedgeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SmithHammerWedgeMaker.maker then SmithHammerWedgeMaker.maker.itemsMade=SmithHammerWedgeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SmithHammerWedgeMaker.maker.skill=math.min(100,SmithHammerWedgeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klin izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"smithhammerwedge.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SmithHammerWedgeMaker.update(dt) if not _G.state then return end; SmithHammerWedgeMaker.dayTimer=SmithHammerWedgeMaker.dayTimer+dt; if SmithHammerWedgeMaker.dayTimer>=30 then SmithHammerWedgeMaker.dayTimer=0; for i=#SmithHammerWedgeMaker.activeMaking,1,-1 do local m=SmithHammerWedgeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SmithHammerWedgeMaker.completeMaking(m); table.remove(SmithHammerWedgeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SmithHammerWedgeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SmithHammerWedgeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SmithHammerWedgeMaker.getStats() return {ironStock=SmithHammerWedgeMaker.ironStock,bronzeStock=SmithHammerWedgeMaker.bronzeStock,woodStock=SmithHammerWedgeMaker.woodStock,leatherStock=SmithHammerWedgeMaker.leatherStock,silverStock=SmithHammerWedgeMaker.silverStock,goldStock=SmithHammerWedgeMaker.goldStock,jewelStock=SmithHammerWedgeMaker.jewelStock,pearlStock=SmithHammerWedgeMaker.pearlStock,productStock=SmithHammerWedgeMaker.productStock,numBuildings=#SmithHammerWedgeMaker.buildings,hasMaker=SmithHammerWedgeMaker.maker~=nil,makerName=SmithHammerWedgeMaker.maker and SmithHammerWedgeMaker.maker.name or "—",makerSkill=SmithHammerWedgeMaker.maker and SmithHammerWedgeMaker.maker.skill or 0,activeMaking=#SmithHammerWedgeMaker.activeMaking,totalProducts=SmithHammerWedgeMaker.totalProducts} end
return SmithHammerWedgeMaker
